from __future__ import annotations

import contextlib
from typing import Callable, Dict, Optional, Sequence, Type

from tilus.hidet.ir.builders import FunctionBuilder
from tilus.hidet.ir.builders.stmt_builder import TypedStmtBuilder as StmtBuilder
from tilus.hidet.ir.dtypes import int32, uint32
from tilus.hidet.ir.expr import Expr, Var, logical_and, tensor_pointer_var, tensor_var
from tilus.hidet.ir.primitives.cuda.elect import elect_one_sync, shfl_sync_i32
from tilus.hidet.ir.primitives.cuda.vars import blockIdx, dim3
from tilus.hidet.ir.stmt import DeclareScope
from tilus.hidet.ir.stmt import Stmt as HidetStmt
from tilus.ir.func import Function
from tilus.ir.inst import Instruction
from tilus.ir.tensor import GlobalTensor, RegisterTensor, SharedTensor, Tensor
from tilus.target import Target, get_current_target, gpgpu_any, nvgpu_sm90


class BaseInstEmitter(StmtBuilder):
    # inst -> emitter
    REGISTRY: Dict[Type[Instruction], Dict[Target, Type["BaseInstEmitter"]]] = {}

    def __init__(self, codegen):
        super().__init__()

        from tilus.backends.codegen import FunctionCodegen

        assert isinstance(codegen, FunctionCodegen)
        self._codegen: FunctionCodegen = codegen

    def assert_is_single_thread(self, inst: Instruction, msg: str) -> None:
        if self.current_num_threads != 1:
            raise ValueError(f"Instruction {inst} requires a single thread: {msg}.")

    def assert_is_a_warp(self, inst: Instruction, msg: str) -> None:
        if self.current_num_threads != 32:
            raise ValueError(f"Instruction {inst} requires a warp (32 threads): {msg}.")

    def assert_is_warp_aligned(self, inst: Instruction, msg: str) -> None:
        if self.current_num_threads != 32 or self.current_thread_group_begin % 32 != 0:
            raise ValueError(
                f"Instruction {inst} requires exactly one warp-aligned warp "
                f"(thread_begin % 32 == 0, num_threads == 32), "
                f"got thread_begin={self.current_thread_group_begin}, num_threads={self.current_num_threads}: {msg}."
            )

    def sync(self):
        optional_sync_call = self.contexts.sync_ctx.sync()
        if optional_sync_call is not None:
            self.append(optional_sync_call)

    def sync_reduce(self, value: Expr, op: str) -> Expr:
        if get_current_target().is_nvgpu():
            from tilus.hidet.ir.primitives.cuda.sync import syncthreads_and, syncthreads_or

            op2sync = {"and": syncthreads_and, "or": syncthreads_or}
            syncthreads_op = op2sync[op]

            if self._codegen.thread_group_stack.stack_depth() == 1:  # all threads in the cta
                return syncthreads_op(value)
            else:
                raise NotImplementedError("sync_reduce in sub-cta thread groups is not implemented")
        else:
            raise NotImplementedError()

    def get_or_allocate_var(self, tensor: Tensor, name: Optional[str] = None) -> Var:
        if tensor in self.tensor2var:
            return self.tensor2var[tensor]
        else:
            if isinstance(tensor, RegisterTensor):
                name = name if name else "regs"
                var = self.declare(
                    tensor_var(name, shape=[tensor.local_size], dtype=tensor.dtype), scope=DeclareScope.Register
                )
            elif isinstance(tensor, SharedTensor):
                name = name if name else "smem"
                var = self.declare(tensor_pointer_var(name, shape=[tensor.size], dtype=tensor.dtype))
            elif isinstance(tensor, GlobalTensor):
                name = name if name else "gmem"
                var = self.declare(tensor_pointer_var(name, shape=[tensor.size], dtype=tensor.dtype))
            else:
                name = name if name else "tmem"
                var = self.declare_var(name, tp=int32)
            self.tensor2var[tensor] = var
            return var

    @property
    def current_thread(self) -> Expr:
        if self._codegen.current_thread is None:
            raise RuntimeError("Current thread is not set")
        return self._codegen.current_thread

    def lane_id(self, name: str = "lane_id") -> Var:
        """Declare and return ``current_thread % 32`` as an int32 variable.

        Emitters that read the lane id across multiple emitted statements should
        cache it once via this helper rather than re-deriving ``current_thread
        % 32`` at each use, both for readability and to let the compiler see a
        single value.
        """
        return self.declare_var(name, int32, self.current_thread % 32)

    def warp_id(self, name: str = "warp_id") -> Var:
        """Declare and return the warp id as a **warp-uniform** int32 variable.

        The raw expression ``current_thread // 32`` is warp-uniform on NVIDIA
        GPUs, but nvcc often can't prove that from the division alone and
        conservatively assumes lanes within a warp can disagree. We broadcast
        via ``__shfl_sync`` from lane 0 so the compiler sees a value every lane
        provably agrees on — this tends to hoist warp-id-only addressing out of
        per-lane loops and eliminate warp-divergent guards.
        """
        from tilus.hidet.ir.primitives.cuda.shfl import shfl_sync

        raw = self.declare_var(name + "_raw", int32, self.current_thread // 32)
        return self.declare_var(
            name,
            int32,
            shfl_sync(uint32(0xFFFFFFFF), raw, src_lane=0, width=32),
        )

    @property
    def current_num_threads(self) -> int:
        return self._codegen.thread_group_stack.num_threads[-1]

    @property
    def current_thread_group_begin(self) -> int:
        return self._codegen.thread_group_stack.thread_begin[-1]

    @property
    def current_thread_group_end(self) -> int:
        return self._codegen.thread_group_stack.thread_end[-1]

    @property
    def current_thread_group_depth(self) -> int:
        return self._codegen.thread_group_stack.stack_depth()

    @property
    def block_rank_in_cluster(self) -> Expr:
        from tilus.hidet.ir.primitives.cuda.cluster import block_rank_in_cluster

        return block_rank_in_cluster()

    @property
    def blocks_per_cluster(self) -> Expr:
        from tilus.hidet.ir.primitives.cuda.cluster import cluster_blocks

        return cluster_blocks()

    @property
    def blockIdx(self) -> dim3:
        return blockIdx

    @property
    def thread_groups(self):
        return self._codegen.thread_group_stack

    @property
    def tensor2var(self) -> Dict[Tensor, Var]:
        return self._codegen.tensor2var

    @property
    def shared_tensor_shared_space_addr(self):
        return self._codegen.shared_tensor_addr

    @property
    def num_warps(self) -> int:
        return self._codegen.function.metadata.num_warps

    @property
    def function(self) -> Function:
        return self._codegen.function

    @property
    def analysis(self):
        return self._codegen.function.metadata.analysis

    @property
    def kernel_params(self) -> Sequence[Var]:
        return self._codegen.builder.params

    def kernel_prepend(self, stmt: Expr | HidetStmt) -> None:
        """Prepend a statement to the kernel function.

        Parameters
        ----------
        stmt: Expr or HidetStmt
            The statement to be prepended.
        """
        self._codegen.builder.scope_stack[-1].insert(0, stmt)

    def kernel_append(self, stmt: Expr | HidetStmt) -> None:
        """Append a statement to the kernel function.

        Parameters
        ----------
        stmt: Expr or HidetStmt
            The statement to be appended.
        """
        self._codegen.builder.append(stmt)

    @property
    def host_builder(self) -> FunctionBuilder:
        return self._codegen.host_builder

    @property
    def builder(self) -> FunctionBuilder:
        return self._codegen.builder

    @property
    def contexts(self):
        return self._codegen.contexts

    def append_extra_param(self, var: Var) -> None:
        """Append an extra parameter to the kernel function.

        This method marks a variable in the host function to be passed as an extra parameter to the kernel function.
        The `var` must be a variable defined in the host function. The kernel function can directly use the `var` in the
        kernel body after this method is called.
        """
        self._codegen.extra_params.append(var)

    def single_thread(self):
        if self.current_num_threads == 1:
            return contextlib.nullcontext()
        elif self.current_num_threads % 32 == 0 and get_current_target().supports(nvgpu_sm90):
            # elect.sync requires sm_90 or higher
            if self.current_num_threads == 32:
                return self.if_then(elect_one_sync())
            else:
                return self.if_then(
                    logical_and(
                        shfl_sync_i32(uint32(0xFFFFFFFF), self.current_thread // 32, int32(0)) == 0,
                        elect_one_sync(),
                    )
                )
        else:
            return self.if_then(self.current_thread == 0)

    def emit(self, inst: Instruction) -> None:
        raise NotImplementedError()


def register_emitter(
    inst_cls: Type[Instruction], *, target: Optional[Target] = None
) -> Callable[[Type[BaseInstEmitter]], Type[BaseInstEmitter]]:
    assert issubclass(inst_cls, Instruction)
    if target is None:
        target = gpgpu_any

    def decorator(emitter_cls: Type[BaseInstEmitter]) -> Type[BaseInstEmitter]:
        assert issubclass(emitter_cls, BaseInstEmitter)

        if inst_cls not in BaseInstEmitter.REGISTRY:
            BaseInstEmitter.REGISTRY[inst_cls] = {}

        if target in BaseInstEmitter.REGISTRY[inst_cls]:
            msg = [
                f"Emitter for instruction {inst_cls} and target {target} already exists",
                f" Registered emitter: {BaseInstEmitter.REGISTRY[inst_cls][target].__module__}",
                f"Registering emitter: {emitter_cls.__module__}",
            ]
            raise ValueError("\n".join(msg))

        BaseInstEmitter.REGISTRY[inst_cls][target] = emitter_cls
        return emitter_cls

    return decorator

@property
def current_thread(self):
    assert self._current_thread is not None
    return self._current_thread

def resolve_inst_emitter(self, inst_cls: Type[Instruction]) -> Optional[Type[BaseInstEmitter]]:
    target = get_current_target()
    emitter_classes = {}
    for registry_inst_cls, registry_emitter_classes in BaseInstEmitter.REGISTRY.items():
        if issubclass(inst_cls, registry_inst_cls):
            emitter_classes.update(registry_emitter_classes)
            break

    matched_target = match_target(target, list(emitter_classes))
    if matched_target is None:
        return None
    return emitter_classes[matched_target]

def check_emitter_existence(self) -> None:
    failed_instructions: Set[Type[Instruction]] = set()
    for inst in collect_instructions(self.function):
        if self.resolve_inst_emitter(inst.__class__) is None:
            failed_instructions.add(inst.__class__)

    if failed_instructions:
        rows = [f"Failed to find emitter for the following instructions (target: {get_current_target()}):"]
        required_targets: list[str] = []
        for inst_cls in failed_instructions:
            for registry_inst_cls, emitter_classes in BaseInstEmitter.REGISTRY.items():
                if issubclass(inst_cls, registry_inst_cls):
                    required_targets.extend([str(target) for target in emitter_classes.keys()])
                    break
            if not required_targets:
                rows.append(f"  - {inst_cls.__name__} (no registered emitters)")
            else:
                rows.append(f"  - {inst_cls.__name__} (registered targets: {', '.join(required_targets)})")
        raise CodeGenerationFailed("\n".join(rows))

def launch_kernel(self, kernel_func: HidetFunction) -> None:
    """Generate the host code to launch the kernel function."""
    if kernel_func.kind == "cuda_kernel":
        func_var = Var(name=kernel_func.name, type=FuncType.from_func(kernel_func))
        dynamic_shared_bytes = (
            kernel_func.attrs.dynamic_smem_bytes if kernel_func.attrs.dynamic_smem_bytes is not None else int32(0)
        )
        assert isinstance(dynamic_shared_bytes, Constant | int), (
            "dynamic shared memory bytes must be a constant integer"
        )
        if int(dynamic_shared_bytes) > get_current_target().properties.shared_memory_per_block:
            raise RuntimeError(
                f"Requested dynamic shared memory bytes {int(dynamic_shared_bytes)} exceed the device limit "
                f"{get_current_target().properties.shared_memory_per_block} for target {get_current_target()}."
            )

        # set max dynamic shared memory bytes if needed
        with self.host_builder.if_then(dynamic_shared_bytes > 48 * 1024):
            self.host_builder.append(set_kernel_max_dynamic_smem_bytes(func_var, dynamic_shared_bytes))

        # launch the kernel
        kernel_args = list(self.host_builder.params) + list(self.extra_params)
        cluster_dim = kernel_func.attrs.cluster_dim if kernel_func.attrs.cluster_dim is not None else 1
        self.host_builder.append(
            LaunchKernelStmt(
                func_var=func_var,
                args=kernel_args,
                grid_dim=normalize_dim3(kernel_func.attrs.grid_dim),  # type: ignore
                cluster_dim=normalize_dim3(cluster_dim),  # type: ignore
                block_dim=normalize_dim3(kernel_func.attrs.block_dim),  # type: ignore
                shared_mem=int32(dynamic_shared_bytes),
                target="cuda",
            )
        )
    else:
        raise NotImplementedError("Only cuda kernel launch is supported now.")

    def visit_BreakStmt(self, stmt):
        self.builder.brk()

    def visit_InstStmt(self, stmt: InstStmt) -> None:
        self.visit(stmt.inst)

    def visit_Instruction(self, inst: Instruction) -> None:
        # insert a comment statement
        skip_comment_instructions = (PrintTensorInst, FormatPrintInst)
        if not isinstance(inst, skip_comment_instructions):
            self.builder.comment(str(self.printer(inst)), style="/*")

        # implement the vm instruction
        emitter_cls = self.resolve_inst_emitter(inst.__class__)
        if emitter_cls is None:
            raise RuntimeError("Can not resolve the emitter for instruction: {}".format(inst.__class__.__name__))
        emitter = emitter_cls(self)
        emitter.emit(inst)
        if inst.output is not None and inst.output not in self.tensor2var:
            raise RuntimeError(
                "The emitter for instruction {} does not set the mapping for its output tensor.".format(
                    inst.__class__.__name__
                )
            )
        self.builder.append(emitter.finish())


class ProgramCodegen(IRFunctor):
    def __call__(self, prog: Program) -> IRModule:
        return self.visit(prog)

    def visit_Program(self, prog: Program) -> IRModule:
        ir_module = IRModule()
        for name, func in prog.functions.items():
            func_codegen = FunctionCodegen()
